/* Genera la cotización en PDF (usa vendor/jspdf.umd.min.js). */
(function(root){
"use strict";
var LOGO = "data:image/jpeg;base64,";
var GREEN=[15,74,55], GOLD=[184,138,46], INK=[18,52,42], MUTED=[88,108,98], LINE=[231,219,186], CREAM=[251,246,234], OK=[30,122,90];
var REGLAS = [
  "La fecha se reserva únicamente con abono previo.",
  "Antes de reservar, consultamos la disponibilidad de tu fecha.",
  "El mobiliario debe devolverse en las mismas condiciones en que se entrega: sin roturas ni manchas. No mojar el mobiliario.",
  "Se entrega un día antes del evento y debe devolverse al día siguiente de la celebración."
];
var ESTADOS = {nueva:"Nueva",fecha_confirmada:"Fecha confirmada",abonada:"Abono recibido",entregada:"Entregada",devuelta:"Devuelta",cancelada:"Cancelada"};

function money(n){ var c=Math.round(Number(n||0)*100); return "$"+(c%100===0 ? String(c/100) : (c/100).toFixed(2)); }
function fecha(d, largo){
  if(!d) return "";
  var x = (d instanceof Date) ? d : new Date(String(d).slice(0,10)+"T12:00:00");
  return x.toLocaleDateString("es-PA", largo ? {weekday:"long",day:"numeric",month:"long",year:"numeric"} : {day:"numeric",month:"long",year:"numeric"});
}
/* Convierte "2 × Arco romano: $20" en {cant, desc, precio} */
function parseLinea(t){
  var m = /^\s*(\d+)\s*[×x]\s*(.*)\s*:\s*([^:]*)$/.exec(String(t));
  if(!m) return {cant:"", desc:String(t), precio:""};
  var p = m[3].trim(), regalo = /regalo/i.test(p);
  return {cant:m[1], desc:m[2], precio:regalo ? "Gratis" : p, gratis:regalo};
}

function build(d){
  var jsPDF = root.jspdf && root.jspdf.jsPDF;
  if(!jsPDF) throw new Error("Falta la librería de PDF");
  var doc = new jsPDF({unit:"mm", format:"a4"});
  var W=210, M=16, R=W-M, y;
  function color(c){ doc.setTextColor(c[0],c[1],c[2]); }
  function fill(c){ doc.setFillColor(c[0],c[1],c[2]); }
  function draw(c){ doc.setDrawColor(c[0],c[1],c[2]); }
  function txt(s,x,yy,opt){ doc.text(Array.isArray(s) ? s : String(s),x,yy,opt); }

  /* Encabezado */
  try{ doc.addImage(LOGO,"JPEG",M,11,30,30); }catch(e){}
  doc.setFont("helvetica","bold"); doc.setFontSize(22); color(GREEN); txt("COTIZACIÓN", R, 22, {align:"right"});
  doc.setFontSize(12); color(INK); txt(d.codigo || "", R, 30, {align:"right"});
  doc.setFont("helvetica","normal"); doc.setFontSize(9.5); color(MUTED);
  txt("Emitida el "+fecha(d.emitida || new Date()), R, 36, {align:"right"});
  txt("Válida por "+(d.validezDias||7)+" días, sujeta a disponibilidad de la fecha", R, 41, {align:"right"});
  draw(GOLD); doc.setLineWidth(0.7); doc.line(M,47,R,47); doc.setLineWidth(0.2); doc.line(M,48.4,R,48.4);

  /* Cliente y evento */
  y = 55;
  fill(CREAM); draw(LINE); doc.setLineWidth(0.3); doc.roundedRect(M,y,R-M,31,2.5,2.5,"FD");
  function par(label, valor, x, yy){
    doc.setFont("helvetica","bold"); doc.setFontSize(8.5); color(MUTED); txt(label, x, yy);
    doc.setFont("helvetica","normal"); doc.setFontSize(10.5); color(INK);
    var lines = doc.splitTextToSize(String(valor||"-"), 80); txt(lines[0], x, yy+4.6);
  }
  var c1=M+5, c2=M+95;
  par("CLIENTE", d.cliente && d.cliente.nombre, c1, y+7);
  par("INSTAGRAM", d.cliente && d.cliente.instagram ? "@"+String(d.cliente.instagram).replace(/^@/,"") : "", c1, y+19);
  par("FECHA DEL EVENTO", fecha(d.evento && d.evento.fecha, true), c2, y+7);
  var ent = d.entrega && d.entrega.tipo==="delivery" ? "Delivery: "+(d.entrega.zona||"por confirmar") : "Retiro en el local";
  par("TIPO DE EVENTO Y ENTREGA", ((d.evento && d.evento.tipo) ? d.evento.tipo+". " : "")+ent, c2, y+19);
  y += 31+8;

  /* Tabla de piezas */
  function cabecera(){
    fill(GREEN); doc.rect(M,y,R-M,8,"F");
    doc.setFont("helvetica","bold"); doc.setFontSize(9.5); doc.setTextColor(255,255,255);
    txt("Cant.", M+4, y+5.4); txt("Descripción", M+20, y+5.4); txt("Precio", R-4, y+5.4, {align:"right"});
    y += 8;
  }
  cabecera();
  (d.lineas||[]).forEach(function(l, i){
    doc.setFont("helvetica","normal"); doc.setFontSize(10);
    var lines = doc.splitTextToSize(l.desc||"", 128), h = lines.length*4.7+3.6;
    if(y+h > 262){ doc.addPage(); y = 20; cabecera(); }
    if(i%2===0){ fill(CREAM); doc.rect(M,y,R-M,h,"F"); }
    color(INK); doc.setFont("helvetica","bold"); txt(l.cant||"", M+4, y+5.2);
    doc.setFont("helvetica","normal"); txt(lines, M+20, y+5.2);
    if(l.gratis){ color(OK); doc.setFont("helvetica","bold"); } else { color(INK); doc.setFont("helvetica","normal"); }
    txt(l.precio||"", R-4, y+5.2, {align:"right"});
    draw(LINE); doc.setLineWidth(0.2); doc.line(M,y+h,R,y+h);
    y += h;
  });
  y += 6;

  /* Resumen y total */
  var res = d.resumen || [];
  if(y + 18 + res.length*6 + 28 > 270){ doc.addPage(); y = 20; }
  res.forEach(function(r){
    doc.setFont("helvetica", r.tono==="ahorro" ? "bold":"normal"); doc.setFontSize(10);
    color(r.tono==="ahorro" ? OK : INK);
    txt(r.label, R-50, y, {align:"right"}); txt(r.valor, R-4, y, {align:"right"});
    y += 6;
  });
  y += 1;
  fill(GREEN); doc.roundedRect(R-92,y,92,13,2.5,2.5,"F");
  doc.setFont("helvetica","bold"); doc.setTextColor(255,255,255); doc.setFontSize(11); txt("Total estimado", R-87, y+8.3);
  doc.setFontSize(16); txt(money(d.total), R-5, y+8.8, {align:"right"});
  y += 13;
  if(d.entrega && d.entrega.tipo==="delivery"){
    doc.setFont("helvetica","italic"); doc.setFontSize(8.5); color(MUTED);
    txt("Más el costo del delivery, que se confirma según el lugar.", R, y+5, {align:"right"}); y += 6;
  }
  if(d.abono!=null && Number(d.abono)>0){
    y += 4;
    doc.setFont("helvetica","normal"); doc.setFontSize(10); color(INK);
    txt("Abono recibido", R-50, y, {align:"right"}); txt(money(d.abono), R-4, y, {align:"right"}); y += 6;
    doc.setFont("helvetica","bold"); color(GREEN);
    txt("Saldo a pagar el día de la entrega", R-50, y, {align:"right"}); txt(money(Math.max(0,Number(d.total)-Number(d.abono))), R-4, y, {align:"right"}); y += 6;
  }
  if(d.estado){
    doc.setFont("helvetica","normal"); doc.setFontSize(9); color(MUTED);
    txt("Estado de la reserva: "+(ESTADOS[d.estado]||d.estado), M, y-(d.abono>0?6:0)+1);
  }
  y += 6;

  /* Notas */
  if(d.notas){
    if(y>245){ doc.addPage(); y=20; }
    doc.setFont("helvetica","bold"); doc.setFontSize(9.5); color(INK); txt("Notas del cliente", M, y);
    doc.setFont("helvetica","normal"); doc.setFontSize(9.5); color(MUTED);
    var nl = doc.splitTextToSize(String(d.notas), R-M); txt(nl.slice(0,4), M, y+5); y += 5+Math.min(4,nl.length)*4.4+4;
  }

  /* Cómo reservar y reglas */
  var depo = d.deposito || 10;
  var alto = 12 + REGLAS.length*0 ;
  doc.setFont("helvetica","normal"); doc.setFontSize(9);
  var bloques = REGLAS.map(function(r){ return doc.splitTextToSize(r, R-M-14); });
  var hReglas = 18 + bloques.reduce(function(s,b){ return s+b.length*4.2+1.6; },0);
  if(y + hReglas > 278){ doc.addPage(); y = 20; }
  fill(CREAM); draw(LINE); doc.setLineWidth(0.3); doc.roundedRect(M,y,R-M,hReglas,2.5,2.5,"FD");
  doc.setFont("helvetica","bold"); doc.setFontSize(10.5); color(GREEN); txt("Cómo reservar", M+5, y+7);
  doc.setFont("helvetica","normal"); doc.setFontSize(9); color(INK);
  txt("Para separar tu fecha se requiere un abono de "+money(depo)+". El resto se paga el día de la entrega.", M+5, y+12.5);
  var yy = y+18;
  bloques.forEach(function(b){
    fill(GOLD); doc.circle(M+6.2, yy-1.1, 0.8, "F");
    color(INK); txt(b, M+10, yy); yy += b.length*4.2+1.6;
  });
  y += hReglas;

  /* Pie en todas las páginas */
  var n = doc.getNumberOfPages();
  for(var p=1;p<=n;p++){
    doc.setPage(p);
    draw(GOLD); doc.setLineWidth(0.4); doc.line(M,284,R,284);
    doc.setFont("helvetica","bold"); doc.setFontSize(9); color(GREEN);
    txt("Arboleda Fest  |  Alquileres que transforman momentos", W/2, 289, {align:"center"});
    doc.setFont("helvetica","normal"); doc.setFontSize(8.5); color(MUTED);
    txt("WhatsApp "+(d.whatsappTexto||"6292-9020")+(n>1 ? "   |   Página "+p+" de "+n : ""), W/2, 293.5, {align:"center"});
  }
  var codigo = String(d.codigo||"cotizacion").replace(/[^A-Za-z0-9-]/g,"");
  return { doc:doc, filename:"Cotizacion-"+codigo+".pdf" };
}

/* Compartir (menú del teléfono) o descargar. Devuelve una promesa con "compartido", "descargado" o "cancelado". */
function entregar(d, opts){
  var r = build(d), blob = r.doc.output("blob"), file = null;
  try{ file = new File([blob], r.filename, {type:"application/pdf"}); }catch(e){}
  function descargar(){
    var url = URL.createObjectURL(blob);
    if(/Instagram|FBAN|FBAV|FB_IAB/i.test(navigator.userAgent)){ window.open(url, "_blank"); }
    else{
      var a = document.createElement("a"); a.href = url; a.download = r.filename;
      document.body.appendChild(a); a.click(); a.remove();
    }
    setTimeout(function(){ URL.revokeObjectURL(url); }, 60000);
    return "descargado";
  }
  if(opts && opts.compartir && file && navigator.canShare && navigator.canShare({files:[file]})){
    return navigator.share({files:[file], title:"Cotización "+(d.codigo||""), text:"Cotización de Arboleda Fest"})
      .then(function(){ return "compartido"; }, function(e){ return (e && e.name==="AbortError") ? "cancelado" : descargar(); });
  }
  return Promise.resolve(descargar());
}

root.AFPDF = { build:build, entregar:entregar, parseLinea:parseLinea, money:money };
})(typeof window !== "undefined" ? window : globalThis);
